"use client";

type FloralProps = {
  className?: string;
  flip?: boolean;
  muted?: boolean;
};

export default function Floral({
  className = "",
  flip = false,
  muted = false,
}: FloralProps) {
  return (
    <div
      className={`pointer-events-none select-none ${className}`}
      style={{
        transform: flip ? "scaleX(-1)" : undefined,
      }}
      aria-hidden="true"
    >
      <svg
        viewBox="0 0 180 260"
        className="h-full w-full overflow-visible"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
      >
        {/* Main stems */}
        <path
          d="M88 258C88 214 91 174 101 136C108 108 119 77 139 45"
          stroke={muted ? "#8F877A" : "#72695D"}
          strokeWidth="1"
          strokeLinecap="round"
          className="floral-draw"
        />

        <path
          d="M90 258C78 213 62 174 47 139C36 113 26 86 22 54"
          stroke={muted ? "#A49B8D" : "#81776A"}
          strokeWidth="0.9"
          strokeLinecap="round"
          className="floral-draw floral-draw-delay"
        />

        <path
          d="M90 258C96 217 116 184 143 159"
          stroke={muted ? "#A49B8D" : "#81776A"}
          strokeWidth="0.8"
          strokeLinecap="round"
        />

        {/* Left branch */}
        <path
          d="M69 190C52 177 40 160 32 141"
          stroke={muted ? "#9E9588" : "#777064"}
          strokeWidth="0.8"
        />

        <path
          d="M59 169C47 165 38 158 30 148"
          stroke={muted ? "#9E9588" : "#777064"}
          strokeWidth="0.7"
        />

        {/* Leaves */}
        <path
          d="M47 139C34 134 25 125 20 113C32 115 42 123 47 139Z"
          fill={muted ? "#A59C8E" : "#81776A"}
          opacity="0.45"
        />

        <path
          d="M61 166C47 162 37 155 31 145C43 148 53 155 61 166Z"
          fill={muted ? "#A59C8E" : "#81776A"}
          opacity="0.35"
        />

        <path
          d="M73 191C61 185 53 177 49 166C60 171 68 179 73 191Z"
          fill={muted ? "#A59C8E" : "#81776A"}
          opacity="0.4"
        />

        <path
          d="M104 184C118 176 129 166 136 154C124 158 113 168 104 184Z"
          fill={muted ? "#A59C8E" : "#81776A"}
          opacity="0.4"
        />

        <path
          d="M113 158C126 151 136 142 141 130C129 135 119 145 113 158Z"
          fill={muted ? "#A59C8E" : "#81776A"}
          opacity="0.32"
        />

        <path
          d="M123 126C135 120 144 111 148 100C137 105 128 114 123 126Z"
          fill={muted ? "#A59C8E" : "#81776A"}
          opacity="0.35"
        />

        {/* Main flower */}
        <g transform="translate(139 45)">
          <circle
            cx="0"
            cy="0"
            r="5"
            fill={muted ? "#A69C8E" : "#807568"}
          />

          <path
            d="M0 -5C-8 -11 -13 -19 -9 -24C-3 -29 3 -21 0 -5Z"
            fill={muted ? "#B0A79A" : "#94887A"}
            opacity="0.8"
          />

          <path
            d="M4 -2C12 -9 21 -11 24 -5C27 2 16 6 4 -2Z"
            fill={muted ? "#B0A79A" : "#94887A"}
            opacity="0.7"
          />

          <path
            d="M2 4C10 9 14 17 9 21C3 25 -2 15 2 4Z"
            fill={muted ? "#B0A79A" : "#94887A"}
            opacity="0.72"
          />

          <path
            d="M-3 3C-11 10 -20 11 -22 5C-24 -1 -14 -5 -3 3Z"
            fill={muted ? "#B0A79A" : "#94887A"}
            opacity="0.65"
          />
        </g>

        {/* Small upper flower */}
        <g transform="translate(22 54) scale(.7)">
          <circle cx="0" cy="0" r="4" fill="#83786A" />

          <path
            d="M0 -4C-7 -9 -10 -16 -6 -20C0 -23 4 -15 0 -4Z"
            fill="#9B9183"
          />

          <path
            d="M3 -2C9 -7 16 -7 18 -2C19 4 11 6 3 -2Z"
            fill="#9B9183"
          />

          <path
            d="M2 3C8 8 9 14 5 17C0 19 -3 11 2 3Z"
            fill="#9B9183"
          />

          <path
            d="M-2 2C-8 7 -14 7 -16 3C-17 -2 -10 -5 -2 2Z"
            fill="#9B9183"
          />
        </g>

        {/* Tiny flowers */}
        <g opacity="0.65">
          <circle cx="149" cy="88" r="2.3" fill="#82786C" />
          <circle cx="154" cy="83" r="1.7" fill="#9A9082" />
          <circle cx="158" cy="89" r="1.5" fill="#9A9082" />
          <circle cx="151" cy="94" r="1.8" fill="#9A9082" />
        </g>

        <g opacity="0.55">
          <circle cx="43" cy="106" r="2" fill="#82786C" />
          <circle cx="48" cy="102" r="1.4" fill="#9A9082" />
          <circle cx="51" cy="108" r="1.6" fill="#9A9082" />
        </g>

        {/* Fine branches */}
        <path
          d="M102 137C116 125 124 113 128 100"
          stroke={muted ? "#AAA194" : "#877D70"}
          strokeWidth="0.6"
        />

        <path
          d="M128 101C136 96 142 88 145 78"
          stroke={muted ? "#AAA194" : "#877D70"}
          strokeWidth="0.6"
        />

        <path
          d="M46 139C38 128 34 118 33 107"
          stroke={muted ? "#AAA194" : "#877D70"}
          strokeWidth="0.6"
        />
      </svg>

      <style jsx>{`
        .floral-draw {
          stroke-dasharray: 260;
          stroke-dashoffset: 260;
          animation: floralDraw 2.4s cubic-bezier(0.22, 1, 0.36, 1) forwards;
        }

        .floral-draw-delay {
          animation-delay: 0.35s;
        }

        @keyframes floralDraw {
          to {
            stroke-dashoffset: 0;
          }
        }
      `}</style>
    </div>
  );
}